/* @autogenerated */
import { Component, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { TranslocoModule } from '@jsverse/transloco';
import { firstValueFrom } from 'rxjs';
import { DocumentDefinition, DocumentFormat } from './document.model';
import { DocumentService, TemplateNotFoundError } from './document.service';

type DocumentStatus = 'loading' | 'ready' | 'failed';

/**
 * Documento de un elemento desde una plantilla Markdown: lo rellena con sus datos, muestra una vista previa y lo
 * descarga como Word o PDF. Lo abre una acción ({@link BaseDocumentAction}) o es la vista de detalle de la entidad
 * (`<document detail="true">`), sin botón de cerrar.
 */
@Component({
  selector: 'entity-document',
  standalone: true,
  imports: [MatButtonModule, MatIconModule, MatProgressBarModule, TranslocoModule],
  templateUrl: './entity-document.component.html',
  styleUrl: './entity-document.component.scss',
})
export class EntityDocumentComponent {
  readonly definition = input.required<DocumentDefinition<any>>();
  readonly item = input<any>();
  /** Si ofrece el botón de cerrar; la vista de detalle no lo tiene. */
  readonly closable = input(true);
  readonly closed = output<void>();

  readonly status = signal<DocumentStatus>('loading');
  /** Clave del error, para el texto. */
  readonly error = signal<'notFound' | 'render' | 'file'>('render');
  readonly preview = signal('');
  /** Formato que se está generando. */
  readonly generating = signal<DocumentFormat | undefined>(undefined);
  readonly formats = computed(() => this.definition().formats ?? (['docx', 'pdf'] as DocumentFormat[]));

  private readonly documents = inject(DocumentService);
  private markdown = '';

  constructor() {
    effect(() => {
      const definition = this.definition();
      const item = this.item();
      if (item !== undefined) {
        untracked(() => this.load(definition, item));
      }
    });
  }

  async load(definition = this.definition(), item = this.item()): Promise<void> {
    this.status.set('loading');
    try {
      this.markdown = await firstValueFrom(this.documents.markdown(definition, item));
      this.preview.set(await this.documents.html(this.markdown));
      this.status.set('ready');
    } catch (error) {
      this.error.set(error instanceof TemplateNotFoundError ? 'notFound' : 'render');
      this.status.set('failed');
    }
  }

  async download(format: DocumentFormat): Promise<void> {
    this.generating.set(format);
    try {
      await this.documents.download(this.markdown, format, this.definition().fileName(this.item()));
    } catch {
      this.error.set('file');
      this.status.set('failed');
    } finally {
      this.generating.set(undefined);
    }
  }
}
